df = df_cleaned.loc[:, ~df_cleaned.columns.str.contains("^Unnamed")].copy()
df["date"] = pd.to_datetime(df["date"])
items = [i for i in item_info if i in df.columns]

long_df = (df.melt("date", items, "item", "price").dropna(subset=["price"])
             .sort_values(["item", "date"]).reset_index(drop=True))
long_df["category"] = long_df["item"].map(item_info)
long_df["year"] = long_df["date"].dt.year
g = long_df.groupby("item")["price"]
long_df["rolling_12mo"] = g.transform(lambda x: x.rolling(12, min_periods=12).mean())
long_df["yoy_pct"] = g.pct_change(12, fill_method=None) * 100      # same month, previous year

# CPI (fetched 13 months early so the first year has a YoY value too)
try:
    cpi = web.DataReader("CPIAUCSL", "fred", df["date"].min().to_period("M").to_timestamp() - pd.DateOffset(months=13),
                         df["date"].max() + pd.offsets.MonthEnd(0)).reset_index()
    cpi.to_csv("cpi_cache.csv", index=False)                       # saved copy, used if FRED is down during the demo
except Exception as e:
    print("⚠ FRED download failed, using the saved copy (cpi_cache.csv):", e)
    cpi = pd.read_csv("cpi_cache.csv", parse_dates=[0])
cpi.columns = ["date", "cpi"]
cpi["date"] = pd.to_datetime(cpi["date"]).dt.to_period("M").dt.to_timestamp()
cpi["cpi"] = pd.to_numeric(cpi["cpi"], errors="coerce")
raw = cpi.set_index("date")["cpi"].sort_index().asfreq("MS")
# Never relabel an older observation as CPI for the dataset's final month.
last_dataset_month = df["date"].max().to_period("M").to_timestamp()
if pd.isna(raw.get(last_dataset_month, np.nan)):
    latest = raw.dropna().index.max()
    latest_label = "none" if pd.isna(latest) else f"{latest:%b %Y}"
    raise ValueError(
        f"CPI-U for {last_dataset_month:%b %Y} is required to match the dataset. "
        f"Latest available observation: {latest_label}. "
        "Rerun when FRED has published that month or use a dataset ending in an available month."
    )
if raw.isna().any():       # Preserve the existing interpolation of internal gaps only.
    print("ℹ CPI-U has no published value for", ", ".join(f"{m:%b %Y}" for m in raw.index[raw.isna()]), "- filled by interpolation")
cpi = raw.interpolate(limit_area="inside").reset_index()
cpi.columns = ["date", "cpi"]
cpi["year"] = cpi["date"].dt.year
cpi["yoy_pct"] = cpi["cpi"].pct_change(12, fill_method=None) * 100
cpi_yoy = cpi.set_index("date")["yoy_pct"]
cpi_roll = cpi.set_index("date")["cpi"].rolling(12, min_periods=12).mean()      # same 12-month average as the items

CATS = sorted(long_df["category"].dropna().unique())
