# =========================
@app.callback(Output("items", "options"), Output("items", "value"), Input("cats", "value"), State("items", "value"))
def sync_items(cats, cur):
    its = sorted(long_df.loc[long_df["category"].isin(cats or []), "item"].unique())
    keep = [i for i in (cur or []) if i in its] or its[:1]
    return [{"label": f"{item_info[i]} — {i}", "value": i} for i in its], keep


@app.callback(Output("item-box", "style"), Output("kpis", "children"), *[Output(f, "figure") for f in FIGS],
              Input("mode", "value"), Input("years", "value"), Input("cats", "value"), Input("items", "value"),
              Input("show-events", "value"))
def update(mode, years, cats, sel, show_events):
    y0, y1 = years
    by = "category" if mode == "category" else "item"
    show = {"flex": "2", "minWidth": "220px", "display": "block" if by == "item" else "none"}
    d = subset(mode, years, cats, sel)
    if d.empty:
        return show, [], *([blank(f"Select at least one {by}")] * len(FIGS))

    cmap = COLORS if by == "category" else None
    fl = first_last(d)
    if fl.empty:
        return show, [], *([blank("No selected item has prices at both ends of this period")] * len(FIGS))
    cpi_year = cpi[cpi["year"].between(y0, y1)].groupby("year")["yoy_pct"].mean()
    last_m = d["date"].max()
    dr = d.dropna(subset=["rolling_12mo"])
    base = dr.groupby(by)["date"].min().max()                      # first month where every plotted line has a value
    base_month = base.to_period("M").to_timestamp()
    last_month = last_m.to_period("M").to_timestamp()
    endpoints = cpi_roll.reindex([base_month, last_month])
    published_endpoints = raw.reindex([base_month, last_month])
    if endpoints.isna().any() or published_endpoints.isna().any():
        msg = f"CPI-U is unavailable for the comparison endpoints ({base:%b %Y} to {last_m:%b %Y})"
        return show, [], *([blank(msg)] * len(FIGS))
    cpi_pct = (endpoints.iloc[1] / endpoints.iloc[0] - 1) * 100  # same 12-mo averages as items
    yoy_now = d.loc[d["date"] == last_m, "yoy_pct"].median()

    # KPIs
    kpis = [kpi("Items compared", f"{len(fl)} of {d['item'].nunique()}", "have prices at both ends of the period"),
            kpi("Median price change", pct(fl["pct"].median()), f"12-mo avg vs 12-mo avg · CPI {pct(cpi_pct)}"),
            kpi("Latest YoY", pct(yoy_now), f"{last_m:%b %Y} · CPI {pct(cpi_yoy.get(last_month, np.nan))}"),
            kpi("Beating inflation", f"{(fl['pct'] > cpi_pct).mean() * 100:.0f}%", "of items rose faster than CPI")]

    # Hero: rebased 12-mo rolling average vs general inflation
    h = dr.sort_values("date").groupby(["date", by], as_index=False)["rolling_12mo"].median()
    h = h[h["date"] >= base]
    h["index"] = h["rolling_12mo"] / h.groupby(by)["rolling_12mo"].transform("first") * 100
    hero = px.line(h, x="date", y="index", color=by, color_discrete_map=cmap, labels={"date": "", "index": "Price Index"})
    hero.update_traces(line_width=2.5, hovertemplate="%{y:.1f}")
    # Exactly two points: shared baseline at 100 and CPI at the final dataset month.
    # The segment is a start-to-end comparison, not the monthly CPI trajectory.
    hero.add_scatter(x=[base, last_m], y=[100, 100 + cpi_pct], mode="lines",
                     line=dict(color="#1d3557", width=3, dash="dot", shape="linear"),
                     hovertemplate="%{x|%b %Y}<br>Index: %{y:.1f}<extra></extra>",
                     name=f"General Inflation ({pct(cpi_pct)})")
    hero.add_hline(y=100, line_dash="dash", line_color="#888", annotation_text="Baseline = 100")
    if "show" in (show_events or []):
        add_key_events(hero, base, last_m)

    # Bar: category = cost of the basket (sum of item prices) 12-mo avg -> 12-mo avg; Item Detail = each item
    t = fl.groupby(fl["category"] if by == "category" else fl.index)[["first", "last"]].sum()
    t.index.name = by
    t["pct"] = (t["last"] / t["first"] - 1) * 100
    t = t.sort_values("pct", ascending=False).reset_index()
    t["category"] = t[by].map(item_info) if by == "item" else t[by]
    bar = px.bar(t, x=by, y="pct", color="category", color_discrete_map=COLORS, custom_data=["first", "last"],
                 text=t["pct"].map("{:+.0f}%".format), category_orders={by: t[by].tolist()},
                 labels={"pct": f"Price increase since {y0} (%)", by: ""})
    bar.update_traces(textposition="outside", cliponaxis=False, textfont=dict(size=12),
                      hovertemplate="%{x}<br>$%{customdata[0]:.2f} → $%{customdata[1]:.2f}<br><b>%{y:+.1f}%</b><extra></extra>")
    bar.update_layout(showlegend=False)
    bar.update_xaxes(tickangle=-30)
    bar.update_yaxes(tickformat="+.0f", ticksuffix="%", range=[min(0, t["pct"].min() * 1.1), max(t["pct"].max() * 1.15, cpi_pct * 1.15)])
    bar.add_hline(y=cpi_pct, line_dash="dot", line_color="#1d3557", annotation_text=f"CPI {pct(cpi_pct)}", annotation_position="top right")

    # Pie: how many items fell in each price-change group
    fl["group"] = pd.cut(fl["pct"], [-np.inf, 0, 20, 50, np.inf], labels=GROUPS[::-1], right=False)
    n = fl["group"].value_counts().reindex(GROUPS)
    n = n[n > 0]                                                       # hide empty slices (no "0%" labels)
    pie = px.pie(names=n.index, values=n.values, hole=0.5, color=n.index, color_discrete_map=G_COLORS)
    pie.update_traces(sort=False, direction="clockwise", textfont_color=[G_TEXT[GROUPS.index(g)] for g in n.index],
                      marker_line=dict(color="white", width=2), textinfo="text",
                      text=[f"{v / n.sum():.0%}<br>({v} item{'s' if v != 1 else ''})" for v in n.values])
    pie.add_annotation(text=f"<b>{n.sum()}</b><br>items", showarrow=False, font_size=20)

    # Box: % change of every item (12-mo averages), grouped by category; each item is a dot
    cat_med = fl.groupby("category")["pct"].median().sort_values(ascending=False)
    cnt = fl["category"].value_counts()
    names = {c: f"{c} ({cnt[c]} item{'s' if cnt[c] > 1 else ''})" for c in cat_med.index}
    box = go.Figure()
    for c in cat_med.index:
        s_ = fl[fl["category"] == c]
        col = COLORS.get(c, "#2a6f97")
        box.add_box(x=s_["pct"], y=[names[c]] * len(s_), orientation="h", boxpoints="all", jitter=0.6, pointpos=0,
                    line_color=col, fillcolor=soft(col), showlegend=False, text=s_.index,
                    marker=dict(color=col, size=9, line=dict(color="white", width=1)),
                    hovertemplate="%{text}: %{x:+.1f}%<extra></extra>")
    for item, r in fl[fl.index.isin(HIGHLIGHT)].iterrows():
        box.add_annotation(x=r["pct"], y=names[r["category"]], showarrow=False, xanchor="left", xshift=6, yshift=14,
                           text=f"{HIGHLIGHT[item]} {r['pct']:+.1f}%" if abs(r["pct"]) < 1 else f"{HIGHLIGHT[item]} {r['pct']:+.0f}%",
                           bgcolor="rgba(255,255,255,0.8)", font=dict(size=10, color="#333"))
    box.add_vline(x=0, line_dash="dash", line_color="#555")
    box.add_vline(x=cpi_pct, line_dash="dot", line_color="#1d3557")
    box.add_annotation(x=cpi_pct, y=1, yref="paper", yanchor="bottom", xanchor="left", showarrow=False,
                       text=f"<b>CPI {pct(cpi_pct)}</b>", font=dict(size=11, color="#1d3557"))
    box.update_yaxes(categoryorder="array", categoryarray=list(names.values()), autorange="reversed", automargin=True)
    box.update_xaxes(tickformat="+.0f", ticksuffix="%", title="Price change, 12-mo average → 12-mo average",
                     range=[min(0, fl["pct"].min() * 1.1), max(fl["pct"].max(), cpi_pct) * 1.3])

    # Bargain finder: item change minus inflation (negative = got cheaper in real terms)
    bf = fl.assign(real=fl["pct"] - cpi_pct).sort_values("real")
    if len(bf) > 2 * TOPN:
        bf = pd.concat([bf.head(TOPN), bf.tail(TOPN)])
    bf["name"] = [short(i) for i in bf.index]
    bf["name"] += bf.groupby("name").cumcount().map(lambda k: "" if k == 0 else f" ({k + 1})")
    bf["verdict"] = np.where(bf["real"] < 0, "Cheaper in real terms", "Pricier in real terms")
    bargain = px.bar(bf, x="real", y="name", orientation="h", color="verdict", custom_data=["pct", "category"],
                     color_discrete_map={"Cheaper in real terms": "#2A6F97", "Pricier in real terms": "#B2182B"},
                     text=bf["pct"].map("{:+.0f}%".format), category_orders={"name": bf["name"].tolist()},
                     labels={"real": "Price change relative to inflation (percentage points)", "name": "", "verdict": ""})
    bargain.update_traces(textposition="outside", cliponaxis=False, textfont=dict(size=11),
                          hovertemplate="%{y} (%{customdata[1]})<br>Price change: %{customdata[0]:+.1f}% vs CPI " + pct(cpi_pct)
                                        + "<br><b>%{x:+.1f} pts vs inflation</b><extra></extra>")
    bargain.update_yaxes(autorange="reversed", automargin=True)
    bargain.update_xaxes(tickformat="+.0f", range=[min(0, bf["real"].min()) * 1.3 - 5, max(0, bf["real"].max()) * 1.3 + 5])
    bargain.add_vline(x=0, line_color="#1d3557", line_width=2)
    bargain.add_annotation(x=0, y=1, yref="paper", yanchor="bottom", showarrow=False, font=dict(size=11, color="#1d3557"),
                           text=f"<b>= inflation (CPI {pct(cpi_pct)})</b>")
    bargain.update_layout(legend=dict(orientation="h", y=-0.14, x=0.5, xanchor="center"))

    # YoY comparison by year vs CPI
    yy = d.groupby(["year", by])["yoy_pct"].median().reset_index()
    yoy = px.line(yy, x="year", y="yoy_pct", color=by, markers=True, color_discrete_map=cmap,
                  labels={"yoy_pct": "YoY change (%)", "year": ""})
    yoy.update_traces(hovertemplate="%{y:.1f}%")
    yoy.add_scatter(x=cpi_year.index, y=cpi_year.values, mode="lines+markers", name="CPI (all items)",
                    line=dict(color="#1d3557", width=3, dash="dot"), hovertemplate="%{y:.1f}%")

    # Heatmap: median YoY % by year, CPI as the top row
    m = d.pivot_table(index=by, columns="year", values="yoy_pct", aggfunc="median")
    cpi_row = pd.DataFrame([cpi_year.reindex(m.columns).values], index=["CPI (all items)"], columns=m.columns)
    m = pd.concat([cpi_row, m])
    heat = px.imshow(m, text_auto=".1f", aspect="auto", color_continuous_scale="RdBu_r",
                     color_continuous_midpoint=0, labels={"color": "YoY %"})
    heat.update_xaxes(type="category", title=None)
    heat.update_yaxes(automargin=True, title=None)
    heat.update_traces(textfont_size=10)
    heat.update_layout(coloraxis_colorbar=dict(thickness=10, len=0.85, title=None))

    return (show, kpis,
            fmt(hero, f"{by.title()} Price Trends vs. General Inflation", hovermode="x unified"),
            fmt(bargain, f"Bargains vs. price risers: change relative to inflation, {y0} → {y1}"),
            fmt(box, f"Did every item rise the same? Price change of each item, by category ({y0}–{y1})"),
            fmt(bar, f"Cost increase by {by}: {y0} → {y1}"),
            fmt(pie, f"How many items got more expensive? {y0} → {y1}"),
            fmt(yoy, "Median YoY change by year vs CPI", hovermode="x unified"),
            fmt(heat, "YoY price change by year (CPI in the top row)"))


@app.callback(Output("layout-saved", "data"), Input("grid", "currentLayout"), State("grid", "breakpointData"),
              prevent_initial_call=True)
def save_layout(cur, bp):
    if not cur or (bp or {}).get("newBreakpoint", "lg") != "lg":      # only remember the full-width arrangement
        raise PreventUpdate
    json.dump([{k: d[k] for k in "ixywh"} for d in cur], open(LAYOUT_FILE, "w"))
    return len(cur)


@app.callback(Output("grid", "itemLayout"), Input("reset", "n_clicks"), prevent_initial_call=True)
def reset_layout(_):
    return DEFAULT_LAYOUT


@app.callback(Output("download", "data"), Input("btn", "n_clicks"), State("mode", "value"), State("years", "value"),
              State("cats", "value"), State("items", "value"), prevent_initial_call=True)
def export(_, mode, years, cats, sel):
    return dcc.send_data_frame(subset(mode, years, cats, sel).to_csv, f"price_trends_{years[0]}_{years[1]}.csv", index=False)


